-- UPDATE B2B-RULE-AUTH-028 SOURCE_SHA256 2beb33b121801853f68a2d6d7b841f518a5fec0300e8bda1587469f82ae76d7f
UPDATE lf_ops.reglas AS r SET titulo='Solicitud de recuperación por soporte, sin OTP automático',descripcion='B2B-AUTH-002 acepta correo validado y muestra idéntica respuesta haya cuenta o no. Para una cuenta elegible, LF_AUTH_BOUNDARY abre expediente con soporte, DNI escaneado, aprobadores configurables 1 o 2 según approvers_required de política 20 (inicial 1), aviso al contacto anterior, auditoría y espera de 48 horas. El servidor emite clave temporal de un solo uso solo al cumplirse todos los controles; no crea desafío OTP PASSWORD_RECOVERY, sesión ni permisos. El reloj de 48 horas NO empieza con la solicitud. Solo el servidor lo inicia cuando (i) terminaron todas las aprobaciones requeridas según la política aplicable y (ii) cada aviso obligatorio al contacto anterior tiene evidencia de estado ENTREGADO, no solo ACCEPTED/QUEUED/SENT; inicio efectivo = instante del último de esos eventos. Rebote, entrega no confirmada o revocación posterior: estado BLOCKED o PAUSED, sin emisión de clave temporal, reasignación ni sesión; una reanudación exige nueva evidencia de entrega y readback auditado. Ante aviso fallido, soporte puede abrir una ruta alternativa gobernada y auditada, sin desbloqueo automático. Contactos candidatos exclusivamente: otro correo o celular previamente registrado y verificado de la misma cuenta antes de iniciar la recuperación, con prueba histórica de titularidad, operación de notificación idempotente y confirmación ENTREGADO; se admite reintento al contacto anterior original. No aceptar nuevos datos declarados durante la solicitud, contactos de un aprobador, terceros ni destinatarios no acreditados. Un contacto secundario NO sustituye por sí solo la notificación obligatoria anterior: la equivalencia y autoridad de sustitución siguen PENDING_HUMAN_DECISION y bloquean el reloj/la liberación hasta aprobación explícita.',valor_config='{"gateway":"LF_AUTH_BOUNDARY","route_id":9,"screen_id":52,"ip_hard_limit":"DENY","email_field_id":299,"ip_signal_mode":"PREVENTIVE_ALERT_ONLY","backend_runtime":"SPRING_BOOT_CORE","frontend_runtime":"NEXTJS_STATIC_EXPORT","provider_binding":"OIDC_PROVIDER_PENDING_M1_SPIKE","identity_protocol":"OIDC_JWT","primary_cta_label":"Solicitar recuperación","aws_identity_target":"AMAZON_COGNITO","production_authorized":false,"success_context_scope":"SUPPORT_CASE_PENDING","arbitrary_redirect_url":"DENY","local_identity_decision":"PENDING_ADR_003_M1_SPIKE","anti_enumeration_rule_id":446,"operational_access_grant":"DENY","password_update_route_id":12,"recovery_verify_route_id":11,"authentication_completion":"DENY","password_update_screen_id":53,"recovery_rate_limit_scope":"FUNCTIONAL_OPERATION_ISOLATED","recovery_verify_screen_id":56,"recovery_rate_limit_rule_id":501,"browser_direct_provider_auth":"DENY","operational_session_creation":"DENY","recovery_rate_limit_policy_id":7,"fail_closed_security_policy_id":18,"architecture_alignment_decision":"DEC-B2B-AUTH-PLATFORM-ALIGNMENT-001","server_generates_correlation_id":true,"password_values_in_recovery_email":"DENY","provider_architecture_security_policy_id":23,"password_fields_before_identity_verification":"DENY","recovery_mode":"SUPPORT_DNI_SCANNED","approvers_policy_id":20,"recovery_hold_hours":48,"auto_recovery_otp":"DENY","hold_start_event":"LAST_REQUIRED_APPROVAL_AND_PREVIOUS_CONTACT_DELIVERED","previous_contact_delivery_requirement":"DELIVERED_RECEIPT","delivery_failure_action":"BLOCK_OR_PAUSE_NO_RELEASE","alternate_delivery_policy":"GOVERNED_ROUTE_PENDING_ACCEPTANCE","alternate_contact_allowlist_status":"PENDING_HUMAN_DECISION","owner_identity_verified":false}'::jsonb WHERE r.id=447 AND r.codigo='B2B-RULE-AUTH-028' AND r.estado='CANDIDATO' AND encode(pg_catalog.sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')='2beb33b121801853f68a2d6d7b841f518a5fec0300e8bda1587469f82ae76d7f';
-- UPDATE B2B-RULE-AUTH-029 SOURCE_SHA256 f7b59a0fc9768ffed87b7c22a5eb681c73571f83610e994b4891972e68c43c9b
UPDATE lf_ops.reglas AS r SET titulo='Validación de expediente de soporte y contexto restringido',descripcion='B2B-AUTH-006 solo habilita PASSWORD_UPDATE_ONLY tras validación server-side de expediente de soporte con DNI escaneado, aprobación 1 o 2 según política 20, avisos al contacto anterior, auditoría y espera 48 horas. La clave temporal es de un solo uso, no satisface MFA ni crea sesión operativa. Estados pendientes, falsos, vencidos o reutilizados se deniegan con respuesta genérica. El reloj de 48 horas NO empieza con la solicitud. Solo el servidor lo inicia cuando (i) terminaron todas las aprobaciones requeridas según la política aplicable y (ii) cada aviso obligatorio al contacto anterior tiene evidencia de estado ENTREGADO, no solo ACCEPTED/QUEUED/SENT; inicio efectivo = instante del último de esos eventos. Rebote, entrega no confirmada o revocación posterior: estado BLOCKED o PAUSED, sin emisión de clave temporal, reasignación ni sesión; una reanudación exige nueva evidencia de entrega y readback auditado. La clave temporal de un solo uso se genera únicamente DESPUÉS de satisfacer el gate; el contexto PASSWORD_UPDATE_ONLY no sustituye la verificación MFA normal.',valor_config='{"grant_mode":"ONE_TIME_TEMP_PASSWORD_SERVER_VALIDATED","accepted_context":"SUPPORT_RECOVERY_APPROVED_48H","recovery_context_scope":"PASSWORD_UPDATE_ONLY","client_context_promotion":"DENY","recovery_verify_route_id":11,"invalid_recovery_error_id":39,"password_update_screen_id":53,"recovery_verify_screen_id":56,"account_existence_exposure":"DENY","server_verification_required":true,"mfa_satisfied_by_recovery_context":"DENY","new_password_payload_before_verification":"DENY","provider_architecture_security_policy_id":23,"operational_authorization_before_completion":"DENY","recovery_hold_hours":48,"auto_recovery_otp":"DENY","hold_start_event":"AFTER_APPROVALS_AND_CONFIRMED_DELIVERY","delivery_failure_action":"BLOCK_OR_PAUSE","temporary_password_issue_guard":"AFTER_48H_ELAPSED_AND_DELIVERY_STILL_VALID","owner_identity_verified":false}'::jsonb WHERE r.id=448 AND r.codigo='B2B-RULE-AUTH-029' AND r.estado='CANDIDATO' AND encode(pg_catalog.sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')='f7b59a0fc9768ffed87b7c22a5eb681c73571f83610e994b4891972e68c43c9b';
