UPDATE lf_ops.reglas AS r SET titulo='Validación por soporte de recuperación B2B',descripcion='B2B-AUTH-006 presenta estado genérico de un expediente de soporte, sin envío ni verificación OTP PASSWORD_RECOVERY. El servidor exige DNI escaneado, aprobadores configurables según política 20, aviso previo, auditoría y 48 horas transcurridas antes de emitir clave temporal de uso único. Sin evidencia, bloquear PASSWORD_UPDATE_ONLY y no revelar existencia de cuenta. El reloj de 48 horas NO empieza con la solicitud. Solo el servidor lo inicia cuando (i) terminaron todas las aprobaciones requeridas según la política aplicable y (ii) cada aviso obligatorio al contacto anterior tiene evidencia de estado ENTREGADO, no solo ACCEPTED/QUEUED/SENT; inicio efectivo = instante del último de esos eventos. Rebote, entrega no confirmada o revocación posterior: estado BLOCKED o PAUSED, sin emisión de clave temporal, reasignación ni sesión; una reanudación exige nueva evidencia de entrega y readback auditado. Ante aviso fallido, soporte puede abrir una ruta alternativa gobernada y auditada, sin desbloqueo automático. Contactos candidatos exclusivamente: otro correo o celular previamente registrado y verificado de la misma cuenta antes de iniciar la recuperación, con prueba histórica de titularidad, operación de notificación idempotente y confirmación ENTREGADO; se admite reintento al contacto anterior original. No aceptar nuevos datos declarados durante la solicitud, contactos de un aprobador, terceros ni destinatarios no acreditados. Un contacto secundario NO sustituye por sí solo la notificación obligatoria anterior: la equivalencia y autoridad de sustitución siguen PENDING_HUMAN_DECISION y bloquean el reloj/la liberación hasta aprobación explícita.',valor_config='{"success_scope":"PASSWORD_UPDATE_ONLY","otp_value_logs":"DENY","mfa_satisfaction":"DENY","verify_screen_id":56,"primary_cta_label":"Verificar código","request_screen_id":52,"delivery_execution":"LF_SERVER_ONLY","otp_value_analytics":"DENY","production_authorized":false,"server_side_generation":"REQUIRED","anti_enumeration_rule_id":446,"delivery_provider_status":"PENDING_CREDENTIALS_IMPLEMENTATION","server_side_verification":"REQUIRED","delivery_contract_rule_id":505,"delivery_confirmed_outcome":"DELIVERED","delivery_confirmation_event":"delivered","provider_acceptance_outcome":"ACCEPTED_PENDING_DELIVERY","operational_session_creation":"DENY","delivery_state_contract_rule_id":505,"provider_acceptance_is_delivery":"DENY","webhook_required_before_verify_ui":false,"provider_acceptance_allows_verify_ui":true,"delivery_failure_account_existence_exposure":"DENY","recovery_method":"SUPPORT_DNI_SCANNED","approval_policy_id":20,"hold_hours":48,"auto_otp_challenge":"DENY","temporary_password":"ONE_TIME_AFTER_APPROVAL","hold_start_event":"LAST_REQUIRED_APPROVAL_AND_DELIVERY","notify_old_contact_status":"DELIVERED_REQUIRED","alternate_contact_accepted":"PENDING_HUMAN_DECISION","owner_identity_verified":false}'::jsonb WHERE r.id=493 AND r.codigo='B2B-RULE-AUTH-037' AND r.estado='CANDIDATO' AND encode(pg_catalog.sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')='b845bb8fe2f4cb700450caea55534b6561287eba9e7ad0c54978a79f6e72ee9a';
-- UPDATE B2B-RULE-AUTH-038 SOURCE_SHA256 481ebfde98e2fc5ca2a709cb739579d79f85a5a582e98d26153386c98b2df0ca
UPDATE lf_ops.reglas AS r SET titulo='Espera de recuperación y estados calculados por servidor',descripcion='B2B-AUTH-006 muestra exclusivamente estados normalizados de expediente y espera de 48 horas calculados server-side; no muestra reenvío OTP ni permite que un temporizador del navegador autorice el desbloqueo. Antes de la aprobación, notificación y vencimiento de espera, no habilita PASSWORD_UPDATE_ONLY. En todos los estados mantiene anti-enumeración. El reloj de 48 horas NO empieza con la solicitud. Solo el servidor lo inicia cuando (i) terminaron todas las aprobaciones requeridas según la política aplicable y (ii) cada aviso obligatorio al contacto anterior tiene evidencia de estado ENTREGADO, no solo ACCEPTED/QUEUED/SENT; inicio efectivo = instante del último de esos eventos. Rebote, entrega no confirmada o revocación posterior: estado BLOCKED o PAUSED, sin emisión de clave temporal, reasignación ni sesión; una reanudación exige nueva evidencia de entrega y readback auditado. Tiempo transcurrido y pausa se calculan desde el ledger server-side, sin que el cliente reanude por acción local.',valor_config='{"hardcoded_expiry":"DENY","verify_screen_id":56,"anti_enumeration_required":true,"hardcoded_resend_countdown":"DENY","numeric_thresholds_in_rule":"DENY","recovery_hold_hours":48,"display_source":"SERVER_RECOVERY_CASE","resend_otp_visible":false,"hold_start":"LATEST_OF_REQUIRED_APPROVAL_COMPLETION_AND_DELIVERY","hold_elapsed_calculation":"SERVER_SIDE_ACCUMULATED_ELIGIBLE_INTERVALS","hold_paused_when_delivery_invalid":true,"restart_requires_fresh_delivery_receipt":true,"wait_hours":48,"owner_identity_verified":false}'::jsonb WHERE r.id=494 AND r.codigo='B2B-RULE-AUTH-038' AND r.estado='CANDIDATO' AND encode(pg_catalog.sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')='481ebfde98e2fc5ca2a709cb739579d79f85a5a582e98d26153386c98b2df0ca';
-- UPDATE B2B-RULE-AUTH-042 SOURCE_SHA256 20ba67e22439a6526b80d9c4fab232f671b1c951b48b9dd465a9cc81f0159521
UPDATE lf_ops.reglas AS r SET titulo='Rate limit aislado de recuperación por soporte',descripcion='Las solicitudes de soporte de B2B-AUTH-002/006 consumen un contador independiente de MFA y correos transaccionales; mismo tratamiento para cuenta existente e inexistente y sujeto derivado del correo canónico mediante secreto server-side. La IP solo eleva señal preventiva de abuso; nunca bloquea por sí sola. Ventanas y umbrales provienen de la política central, sin duplicarlos. La recuperación por soporte conserva el mismo tratamiento para cuenta existente/inexistente incluso al pausar el reloj por aviso no entregado; mensajes y códigos observables no revelan si hay expediente real.',valor_config='{"ip_escalation":"RISK_OR_ANTIBOT","ip_hard_limit":"DENY","resource_code":"AUTH_SUPPORT_RECOVERY_REQUEST","ip_signal_mode":"PREVENTIVE_ALERT_ONLY","counter_subject":"PRIVACY_PRESERVING_DERIVED_SUBJECT_KEY","rate_limit_policy_id":7,"abuse_security_policy_id":22,"anti_enumeration_required":true,"counter_subject_derivation":"HMAC(SERVER_CANONICAL_EMAIL_VALUE,SERVER_SECRET)","numeric_thresholds_in_rule":"DENY","anti_bot_security_policy_id":17,"account_existence_dependency":"DENY","functional_operation_isolation":"REQUIRED","counter_subject_secret_location":"RUNTIME_SECRET_OUTSIDE_LF_OPS","counter_consumed_when_account_unknown":true,"other_otp_operation_counter_interference":"DENY","transactional_email_counter_interference":"DENY","functional_operation":"SUPPORT_RECOVERY","automatic_otp_send":"DENY","recovery_failure_ui":"ANTI_ENUMERATION_GENERIC","delivery_state_reveal_to_unauthenticated":"DENY","owner_identity_verified":false}'::jsonb WHERE r.id=501 AND r.codigo='B2B-RULE-AUTH-042' AND r.estado='CANDIDATO' AND encode(pg_catalog.sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')='20ba67e22439a6526b80d9c4fab232f671b1c951b48b9dd465a9cc81f0159521';
-- UPDATE REG_CLIENT_RECOVERY_IDV_OUTCOME_001 SOURCE_SHA256 772b74d119e1b471e997432273585bc410f081567bd87c26c58dcfacfb4eb30d
UPDATE lf_ops.reglas AS r SET titulo='Resultado IDV y comprobante manual Q11 distintos',descripcion='Un resultado automático IDV VERIFIED solo procede del proveedor integrado y verificado, nunca de una simulación ni del DNI solo. En forma separada, soporte Q11 emite comprobante server-side tras escaneo DNI, creador distinto del aprobador, avisos a celular y correo anteriores, auditoría y 48 horas de espera. Ni falla, ni falta de proveedor, ni caso en revisión autoriza reasignación o acceso. La UI no ve respuestas crudas de proveedor ni documentos. El comprobante manual Q11 se valida con aprobador diferente, dos avisos ENTREGADOS y 48 horas de espera elegible; falta de entrega o rechazo mantiene DENY. No confundir un expediente de soporte con el outcome externo VERIFIED. Selfie: NO_AUTORIZADA_POR_AHORA, no implementada, sin reglas operativas, sin captura ni envío; proveedor IDV PENDING_SELECTION y sin atribución de VERIFIED automático.',valor_config='{"flow":"RECOVERY_FLOW","front":"CLIENTE","outcomes":{"IDENTITY_VALIDATION_DENIED":{"next":"GENERIC_RECOVERY_FAILURE","rebind":"DENY","operational_access":"DENY"},"IDENTITY_VALIDATION_VERIFIED":{"rebind":"ALLOW_VIA_REG_CLIENT_RECOVERY_REBIND_ATOMIC_001","operational_access":"AFTER_SUCCESSFUL_REBIND_ONLY"},"IDENTITY_VALIDATION_RISK_BLOCKED":{"next":"TEMPORARY_SECURITY_STOP","rebind":"DENY","operational_access":"DENY"},"IDENTITY_VALIDATION_RETRYABLE_FAILURE":{"next":"RETRY_SUBJECT_TO_PROVIDER_POLICY","rebind":"DENY","operational_access":"DENY"},"IDENTITY_VALIDATION_SERVICE_UNAVAILABLE":{"next":"RETRY_LATER_NO_BYPASS","rebind":"DENY","operational_access":"DENY"}},"allowed_outcomes":["IDENTITY_VALIDATION_VERIFIED","IDENTITY_VALIDATION_RETRYABLE_FAILURE","IDENTITY_VALIDATION_DENIED","IDENTITY_VALIDATION_RISK_BLOCKED","IDENTITY_VALIDATION_SERVICE_UNAVAILABLE"],"source_rule_code":"REG_CLIENT_RECOVERY_IDV_STEPUP_001","source_decision_numbers":[71,103,104],"support_can_override_outcome":"DENY","provider_result_normalization":"SERVER_SIDE_REQUIRED","provider_raw_payload_to_client":"DENY","provider_specific_reason_to_client":"DENY","q11_manual_proof":"Q11_TWO_DISTINCT_APPROVERS_48H","manual_approval_not_provider_verified":true,"selfie":"INACTIVE","manual_q11_release_gate":"TWO_DISTINCT_PEOPLE_OLD_PHONE_AND_EMAIL_DELIVERED_48H","idv_provider":"PENDING_SELECTION","identity_verified_by_selfie":false,"owner_identity_verified":false}'::jsonb WHERE r.id=511 AND r.codigo='REG_CLIENT_RECOVERY_IDV_OUTCOME_001' AND r.estado='VIGENTE' AND encode(pg_catalog.sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')='772b74d119e1b471e997432273585bc410f081567bd87c26c58dcfacfb4eb30d';
-- UPDATE REG_CLIENT_RECOVERY_IDV_STEPUP_001 SOURCE_SHA256 95185d992bf1c7e03773796030024b3642f26757fcea899f1ed02fda681d42b4
UPDATE lf_ops.reglas AS r SET titulo='Step-up Cliente con soporte Q11 e IDV sin seleccionar',descripcion='REC_001 permite, sin celular anterior, la ruta Q11 con DNI escaneado, dos personas distintas (una registra y otra aprueba), notificación a celular y correo anteriores, auditoría y 48 horas de espera. El celular actual debe seguir verificado en ONB_002, sin que su OTP sustituya identidad. El proveedor IDV no está elegido y selfie no está decidida: ninguno se presume implementado. Riesgo HIGH conserva bloqueo y revisión. El reloj de 48 horas NO empieza con la solicitud. Solo el servidor lo inicia cuando (i) terminaron todas las aprobaciones requeridas según la política aplicable y (ii) cada aviso obligatorio al contacto anterior tiene evidencia de estado ENTREGADO, no solo ACCEPTED/QUEUED/SENT; inicio efectivo = instante del último de esos eventos. Rebote, entrega no confirmada o revocación posterior: estado BLOCKED o PAUSED, sin emisión de clave temporal, reasignación ni sesión; una reanudación exige nueva evidencia de entrega y readback auditado. Para Q11 la aprobación requiere dos personas diferentes: operador creador y operador aprobador; ambos avisos al celular y correo anteriores deben quedar ENTREGADOS con evidencia; si falla uno, el reloj no empieza o queda en PAUSED. Ante aviso fallido, soporte puede abrir una ruta alternativa gobernada y auditada, sin desbloqueo automático. Contactos candidatos exclusivamente: otro correo o celular previamente registrado y verificado de la misma cuenta antes de iniciar la recuperación, con prueba histórica de titularidad, operación de notificación idempotente y confirmación ENTREGADO; se admite reintento al contacto anterior original. No aceptar nuevos datos declarados durante la solicitud, contactos de un aprobador, terceros ni destinatarios no acreditados. Un contacto secundario NO sustituye por sí solo la notificación obligatoria anterior: la equivalencia y autoridad de sustitución siguen PENDING_HUMAN_DECISION y bloquean el reloj/la liberación hasta aprobación explícita. Selfie: NO_AUTORIZADA_POR_AHORA, no implementada, sin reglas operativas, sin captura ni envío; proveedor IDV PENDING_SELECTION y sin atribución de VERIFIED automático.',valor_config='{"flow":"RECOVERY_FLOW","front":"CLIENTE","triggers":["OLD_PHONE_UNAVAILABLE","PHONE_MULTI_DNI_RISK_HIGH"],"raw_pii_in_logs":"DENY","provider_binding":"PENDING_CANONICAL_IDV_PROVIDER","rebind_rule_code":"REG_CLIENT_RECOVERY_REBIND_ATOMIC_001","support_override":"DENY","target_route_code":"CLIENT_RECOVERY","raw_pii_in_analytics":"DENY","target_screen_mapping":"REC_001","source_decision_numbers":[71,103,104],"required_identity_outcome":"IDV_VERIFIED_OR_Q11_MANUAL_PROOF","provider_agnostic_contract":true,"current_phone_control_source":"ONB_002_SAME_SERVER_SESSION","source_architecture_decision":"DEC-CLIENT-AUTH-SESSION-RUNTIME-001","account_rebind_before_verified":"DENY","current_phone_control_required":true,"dni_knowledge_alone_sufficient":false,"raw_provider_payload_to_client":"DENY","knowledge_based_questions_default":"DENY","operational_access_before_verified":"DENY","current_phone_control_alone_sufficient":false,"email_otp_approved_as_client_recovery_factor":false,"support_q11_path":"TWO_PERSON_DNI_48H","support_approvers_required":2,"previous_contact_notice":["PHONE","EMAIL"],"hold_hours":48,"selfie":"DISABLED_OWNER_DECISION","selfie_operational_rules":"NONE","idv_provider":"PENDING_SELECTION","q11_approval_separation":"CREATOR_NE_APPROVER","previous_contacts_required":["OLD_PHONE","OLD_EMAIL"],"previous_contacts_delivery":"ALL_DELIVERED","hold_start":"AFTER_APPROVAL_AND_ALL_DELIVERED","hold_invalid_delivery":"BLOCK_OR_PAUSE","alternate_acceptance":"PENDING_HUMAN_DECISION","owner_identity_verified":false}'::jsonb WHERE r.id=510 AND r.codigo='REG_CLIENT_RECOVERY_IDV_STEPUP_001' AND r.estado='VIGENTE' AND encode(pg_catalog.sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')='95185d992bf1c7e03773796030024b3642f26757fcea899f1ed02fda