-- UPDATE REG_CLIENT_RECOVERY_PHONE_CONTROL_001 SOURCE_SHA256 2043f8575951db0e61cdeeec58624f22c035425e929096ae973b9ef159a89dfa
UPDATE lf_ops.reglas AS r SET titulo='Celular actual verificado y recuperación Q11 sin el anterior',descripcion='REC_001 reutiliza el celular actual verificado en ONB_002 mientras la misma sesión siga válida. Si el anterior está disponible, verificar su OTP por la ruta existente; si no, pasar a soporte Q11 con DNI escaneado, dos personas distintas, avisos a celular/correo anteriores, auditoría y 48 horas. Ningún camino permite reasociación antes del comprobante válido ni revela existencia de cuenta. El OTP al celular nuevo NO inicia recuperación. El reloj de 48 horas NO empieza con la solicitud. Solo el servidor lo inicia cuando (i) terminaron todas las aprobaciones requeridas según la política aplicable y (ii) cada aviso obligatorio al contacto anterior tiene evidencia de estado ENTREGADO, no solo ACCEPTED/QUEUED/SENT; inicio efectivo = instante del último de esos eventos. Rebote, entrega no confirmada o revocación posterior: estado BLOCKED o PAUSED, sin emisión de clave temporal, reasignación ni sesión; una reanudación exige nueva evidencia de entrega y readback auditado. Q11 exige evidencia ENTREGADO en celular y correo anteriores o bloqueo; contacto alterno no sustituye automáticamente sin decisión humana. Selfie: NO_AUTORIZADA_POR_AHORA, no implementada, sin reglas operativas, sin captura ni envío; proveedor IDV PENDING_SELECTION y sin atribución de VERIFIED automático.',valor_config='{"source_state":"RECOVERY_FLOW","source_screen":"ONB_003","target_route_code":"CLIENT_RECOVERY","current_phone_role":"NEW_VERIFIED_PHONE_CANDIDATE","reask_current_phone":"DENY","show_full_old_phone":"DENY","ask_old_phone_access":true,"old_phone_accessible":"VERIFY_OLD_PHONE_OTP","old_phone_otp_channel":"whatsapp","old_phone_unavailable":"SUPPORT_Q11_DNI_TWO_PERSON_48H","target_screen_mapping":"REC_001","source_decision_number":103,"old_phone_otp_operation":"OTP_OP_RECUPERAR_CLAVE","old_phone_otp_field_code":"CAMPO_OTP_CODE","repeat_current_phone_otp":false,"source_architecture_decision":"DEC-CLIENT-AUTH-SESSION-RUNTIME-001","current_verified_phone_source":"ONB_001_PLUS_ONB_002","identity_validation_rule_code":"REG_IDV_PROGRESSIVE_001","same_session_binding_required":true,"previous_contact_notice":["PHONE","EMAIL"],"manual_q11_distinct_people":true,"new_phone_otp_starts_48h":false,"old_contacts_delivery_gate":"PHONE_AND_EMAIL_DELIVERED","hold_start":"AFTER_APPROVAL_AND_DELIVERED","selfie":"NO_NOT_ACTIVE","owner_identity_verified":false}'::jsonb WHERE r.id=507 AND r.codigo='REG_CLIENT_RECOVERY_PHONE_CONTROL_001' AND r.estado='VIGENTE' AND encode(pg_catalog.sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')='2043f8575951db0e61cdeeec58624f22c035425e929096ae973b9ef159a89dfa';
-- UPDATE REG_CLIENT_RECOVERY_REBIND_ATOMIC_001 SOURCE_SHA256 88b650cd7f9c964281f40b23823c3000b0da9bf91d3b5ef423d453f2129f5557
UPDATE lf_ops.reglas AS r SET titulo='Reasignación Cliente atómica e idempotente tras comprobante Q11',descripcion='Solo reasociar celular a cuenta Cliente con sesión ONB_002 válida, verificación de unicidad y una prueba aprobada. Sin celular anterior, admitir comprobante Q11 server-side tras DNI escaneado, creación y aprobación por personas distintas, aviso a celular/correo anteriores, auditoría y espera 48 horas. Selfie no autorizada; IDV externo no elegido. Antes de commit revalidar riesgo HIGH y revocar acceso y sesiones del principal anterior; evitar escrituras parciales o dobles vínculos. El reloj de 48 horas NO empieza con la solicitud. Solo el servidor lo inicia cuando (i) terminaron todas las aprobaciones requeridas según la política aplicable y (ii) cada aviso obligatorio al contacto anterior tiene evidencia de estado ENTREGADO, no solo ACCEPTED/QUEUED/SENT; inicio efectivo = instante del último de esos eventos. Rebote, entrega no confirmada o revocación posterior: estado BLOCKED o PAUSED, sin emisión de clave temporal, reasignación ni sesión; una reanudación exige nueva evidencia de entrega y readback auditado. Para Q11 verificar creador distinto del aprobador, DNI escaneado y entrega efectiva al antiguo celular y correo, y esperar 48 horas elegibles con readback del estado no PAUSED inmediatamente antes del commit. Ni aceptación del proveedor ni aviso no entregado permiten rebind. Selfie: NO_AUTORIZADA_POR_AHORA, no implementada, sin reglas operativas, sin captura ni envío; proveedor IDV PENDING_SELECTION y sin atribución de VERIFIED automático.',valor_config='{"idempotency":"REQUIRED","atomic_commit":"REQUIRED","audit_storage":"lf_client.security_events","auth_provider":"SUPABASE_AUTH","audit_rule_code":"REG_AUD_004","raw_dni_in_logs":"DENY","raw_phone_in_logs":"DENY","concurrent_conflict":"GENERIC_FAILURE_NO_PARTIAL_COMMIT","auth_principal_rebind":"UPDATE_CLIENT_ACCOUNT_AUTH_USER_ID_ATOMICALLY_AFTER_VERIFIED_RECOVERY","source_decision_number":103,"account_binding_storage":"lf_client.client_accounts + lf_client.client_phone_bindings","old_phone_otp_operation":"OTP_OP_RECUPERAR_CLAVE","accepted_recovery_proofs":["OLD_PHONE_OTP_VERIFIED","IDENTITY_VALIDATION_VERIFIED","SUPPORT_Q11_TWO_PERSON_DNI_48H_APPROVED"],"current_phone_otp_source":"ONB_002_SAME_SERVER_SESSION","precommit_risk_rule_code":"REG_RISK_PHONE_MULTI_DNI_001","identity_stepup_rule_code":"REG_CLIENT_RECOVERY_IDV_STEPUP_001","current_phone_otp_required":true,"identity_outcome_rule_code":"REG_CLIENT_RECOVERY_IDV_OUTCOME_001","post_rebind_access_rule_code":"REG_CLIENT_RECOVERY_ACCESS_AFTER_REBIND_001","source_architecture_decision":"DEC-CLIENT-AUTH-SESSION-RUNTIME-001","target_phone_uniqueness_rule":"REG_UNI_002","old_principal_business_access":"REVOKE_IMMEDIATELY","old_principal_session_revocation":"SERVER_SIDE_REQUIRED","operational_access_before_commit":"DENY","invalidate_previous_phone_binding":true,"manual_q11_hold_hours":48,"manual_q11_distinct_approver":true,"manual_q11_previous_notifications":["PHONE","EMAIL"],"selfie":"UNDECIDED","q11_hold_start":"LATEST_APPROVAL_COMPLETED_AND_REQUIRED_NOTIFICATIONS_DELIVERED","old_notifications_required_delivered":["PHONE","EMAIL"],"no_release_if_paused":true,"server_clock_only":true,"secondary_contact_cannot_substitute_without_owner_decision":true,"owner_identity_verified":false}'::jsonb WHERE r.id=508 AND r.codigo='REG_CLIENT_RECOVERY_REBIND_ATOMIC_001' AND r.estado='VIGENTE' AND encode(pg_catalog.sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')='88b650cd7f9c964281f40b23823c3000b0da9bf91d3b5ef423d453f2129f5557';
-- UPDATE REG_ONB002_UI_STATES_001 SOURCE_SHA256 60d5b3105f550a927efe8bcaede671cbd9e8afef83b610ec68bc18207382f8b0
UPDATE lf_ops.reglas AS r SET titulo='ONB_002 — estados OTP y SMS por soporte',descripcion='ONB_002 conserva estados A normal, B contador agotado y C OTP incorrecto; tiempos y CTA consumen contratos server-side y tokens de diseño. Ante fallo de WhatsApp no activa SMS automáticamente. SMS Intico solo aparece por contingencia habilitada por soporte con auditoría; en caso contrario permanece oculto. El OTP demuestra control del celular, no identidad civil. Contingencia SMS Intico sólo si soporte la habilitó. Si el usuario deriva a recuperación REC_001, el OTP de ONB_002 no inicia las 48 horas ni habilita readbind por sí solo; rige la prueba de aprobación y entrega de aviso histórico de Q11. Selfie: NO_AUTORIZADA_POR_AHORA, no implementada, sin reglas operativas, sin captura ni envío; proveedor IDV PENDING_SELECTION y sin atribución de VERIFIED automático.',valor_config='{"title":"Te enviamos un código","state_A":{"code":"NORMAL","timer_text":"(00:45)","resend_label":"Reenviar código","resend_muted":true,"cta_visual_state":"ACTIVE_GREEN","timer_underlined":false,"resend_underlined":true},"state_B":{"code":"COUNTER_EXHAUSTED","resend_label":"Reenviar código","cta_visual_state":"PRIMARY_TOKEN","sms_fallback_visibility":"HIDE_UNLESS_SUPPORT_ACTIVATED","runtime_timing_status":"SERVER_POLICY_REQUIRED"},"state_C":{"code":"INVALID_CODE","error_copy":"Código incorrecto. Revisa e intenta de nuevo.","otp_border":"ERROR_RED","cta_visual_state":"ACTIVE_GREEN"},"otp_slots":6,"layout_shift":false,"runtime_refs":["REG_RATE_005","REG_SEG_001","REG_SEG_002","OTP_POL_DEFAULT"],"vertical_anchors":{"h1":"MATCH_ONB001_H1","trust_row":"MATCH_ONB001_TRUST_ROW","primary_cta":"MATCH_ONB001_PRIMARY_CTA"},"error_line_reserved":true,"source_visual_decision":"VD_CLIENT_ONB002_WEB_V06_20260820","sms_fallback_mode":"SUPPORT_ONLY","sms_provider":"INTICO","auto_sms_fallback":"DENY","recovery_timer_started_by_current_phone_otp":false,"selfie_recovery_path":"INACTIVE","idv_provider_status":"PENDING_SELECTION","owner_identity_verified":false}'::jsonb WHERE r.id=568 AND r.codigo='REG_ONB002_UI_STATES_001' AND r.estado='VIGENTE' AND encode(pg_catalog.sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')='60d5b3105f550a927efe8bcaede671cbd9e8afef83b610ec68bc18207382f8b0';
-- INSERT CANDIDATO B2B-RULE-RECOVERY-SUPPORT-001 LINKS B2B-AUTH-002,B2B-AUTH-003,B2B-AUTH-006
WITH inserted AS (INSERT INTO lf_ops.reglas(codigo,categoria,titulo,descripcion,valor_config,estado,origen,pendiente_decision,created_by) VALUES ('B2B-RULE-RECOVERY-SUPPORT-001','AUTH','Recuperación asistida B2B con 48 horas y clave temporal','Soporte registra DNI escaneado; la política central 20 determina 1 o 2 aprobadores (inicial 1). Exigir aviso al contacto previo, auditoría y 48 horas antes de emitir clave temporal de uso único limitada a contraseña nueva. No ofrecer OTP PASSWORD_RECOVERY ni establecer sesión antes de nuevo login y MFA conforme a política. Si falta evidencia, bloquear sin revelar existencia de usuario. El reloj de 48 horas NO empieza con la solicitud. Solo el servidor lo inicia cuando (i) terminaron todas las aprobaciones requeridas según la política aplicable y (ii) cada aviso obligatorio al contacto anterior tiene evidencia de estado ENTREGADO, no solo ACCEPTED/QUEUED/SENT; inicio efectivo = instante del último de esos eventos. Rebote, entrega no confirmada o revocación posterior: estado BLOCKED o PAUSED, sin emisión de clave temporal, reasignación ni sesión; una reanudación exige nueva evidencia de entrega y readback auditado. Ante aviso fallido, soporte puede abrir una ruta alternativa gobernada y auditada, sin desbloqueo automático. Contactos candidatos exclusivamente: otro correo o celular previamente registrado y verificado de la misma cuenta antes de iniciar la recuperación, con prueba histórica de titularidad, operación de notificación idempotente y confirmación ENTREGADO; se admite reintento al contacto anterior original. No aceptar nuevos datos declarados durante la solicitud, contactos de un aprobador, terceros ni destinatarios no acreditados. Un contacto secundario NO sustituye por sí solo la notificación obligatoria anterior: la equivalencia y autoridad de sustitución siguen PENDING_HUMAN_DECISION y bloquean el reloj/la liberación hasta aprobación explícita.','{"approvers_policy_id":20,"initial_approvers_required":1,"hold_hours":48,"document":"SCANNED_DNI","previous_contact_notification":true,"audit":true,"temporary_password":"ONE_TIME","state":"PROPOSED_NOT_ACTIVE","hold_start":"AFTER_ALL_APPROVALS_AND_PREVIOUS_DELIVERED","delivery_failure":"BLOCK_OR_PAUSE","alt_contacts":"CANDIDATE_PENDING_OWNER_AUTHORIZATION","identity_verified":false}'::jsonb,'CANDIDATO','LF_GOVERNANCE_PROPOSAL',true,'ARCHITECT_DRAFT') RETURNING id) INSERT INTO lf_ops.reglas_pantallas(regla_id,pantalla_id,nota) SELECT inserted.id,d.pantalla_id,'DOCUMENTAL_PENDING_HUMAN_GATES' FROM inserted CROSS JOIN (VALUES (52),(53),(56)) AS d(pantalla_id);
-- INSERT CANDIDATO REG_CLIENT_RECOVERY_SUPPORT_Q11_001 LINKS REC_001
WITH inserted AS (INSERT INTO lf_ops.reglas(codigo,categoria,titulo,descripcion,valor_config,estado,origen,pendiente_decision,created_by) VALUES ('REG_CLIENT_RECOVERY_SUPPORT_Q11_001','RECOVERY','Recuperación Cliente Q11 por dos personas','Sin celular anterior, soporte registra DNI escaneado y una segunda persona distinta aprueba. Avisar al celular y correo anteriores; conservar auditoría y bloquear 48 horas antes de emitir comprobante apto para rebind atómico del celular verificado en ONB_002. Selfie y proveedor IDV quedan sin decidir; no fingir evidencia ni liberar cuenta antes de completar el proceso. El reloj de 48 horas NO empieza con la solicitud. Solo el servidor lo inicia cuando (i) terminaron todas las aprobaciones requeridas según la política aplicable y (ii) cada aviso obligatorio al contacto anterior tiene evidencia de estado ENTREGADO, no solo ACCEPTED/QUEUED/SENT; inicio efectivo = instante del último de esos eventos. Rebote, entrega no confirmada o revocación posterior: estado BLOCKED o PAUSED, sin emisión de clave temporal, reasignación ni sesión; una reanudación exige nueva evidencia de entrega y readback auditado. Q11 exige ENTREGADO en celular y correo anteriores. Ante aviso fallido, soporte puede abrir una ruta alternativa gobernada y auditada, sin desbloqueo automático. Contactos candidatos exclusivamente: otro correo o celular previamente registrado y verificado de la misma cuenta antes de iniciar la recuperación, con prueba histórica de titularidad, operación de notificación idempotente y confirmación ENTREGADO; se admite reintento al contacto anterior original. No aceptar nuevos datos declarados durante la solicitud, contactos de un aprobador, terceros ni destinatarios no acreditados. Un contacto secundario NO sustituye por sí solo la notificación obligatoria anterior: la equivalencia y autoridad de sustitución siguen PENDING_HUMAN_DECISION y bloquean el reloj/la liberación hasta aprobación explícita. Selfie: NO_AUTORIZADA_POR_AHORA, no implementada, sin reglas operativas, sin captura ni envío; proveedor IDV PENDING_SELECTION y sin atribución de VERIFIED automático.','{"approvers_required":2,"hold_hours":48,"scanned_dni":true,"notifications":["PREVIOUS_PHONE","PREVIOUS_EMAIL"],"creator_differs_from_approver":true,"selfie":"NO_NOT_ACTIVE","idv":"PENDING_SELECTION","state":"PROPOSED_NOT_ACTIVE","hold_start":"AFTER_CREATOR_APPROVER_SEPARATION_AND_PHONE_EMAIL_DELIVERED","delivery_failure":"BLOCK_OR_PAUSE","idv_provider":"PENDING_SELECTION","alternate_contacts":"PENDING_HUMAN_DECISION","identity_verified":false}'::jsonb,'CANDIDATO','LF_GOVERNANCE_PROPOSAL',true,'ARCHITECT_DRAFT') RETURNING id) INSERT INTO lf_ops.reglas_pantallas(regla_id,pantalla_id,nota) SELECT inserted.id,d.pantalla_id,'DOCUMENTAL_PENDING_HUMAN_GATES' FROM inserted CROSS JOIN (VALUES (58)) AS d(pantalla_id);
-- INSERT CANDIDATO REG_ONB002_SMS_SUPPORT_GATE_001 LINKS ONB_002
WITH inserted AS (INSERT INTO lf_ops.reglas(codigo,categoria,titulo,descripcion,valor_config,estado,origen,pendiente_decision,created_by) VALUES ('REG_ONB002_SMS_SUPPORT_GATE_001','AUTH','SMS Intico como contingencia no automática','En ONB_002 el canal de OTP Cliente es WhatsApp. Ante falla no activar fallback SMS automáticamente: registrar incidente, permitir reintento según política y comunicar a soporte. Solo soporte puede habilitar SMS Intico con evidencia auditable; el frontend no selecciona proveedor, no duplica OTP ni convierte control de teléfono en identidad personal. La activación de soporte SMS no inicia ni levanta la espera de recuperación Q11. Selfie: NO_AUTORIZADA_POR_AHORA, no implementada, sin reglas operativas, sin captura ni envío; proveedor IDV PENDING_SELECTION y sin atribución de VERIFIED automático.','{"channel":"WHATSAPP","contingency":"INTICO_SMS","activation":"SUPPORT_ONLY","auto_fallback":"DENY","state":"PROPOSED_NOT_ACTIVE","recovery_clock_from_otp":"DENY","selfie":"INACTIVE","identity_verified":false}'::jsonb,'CANDIDATO','LF_GOVERNANCE_PROPOSAL',true,'ARCHITECT_DRAFT') RETURNING id) INSERT INTO lf_ops.reglas_pantallas(regla_id,pantalla_id,nota) SELECT inserted.id,d.pantalla_id,'DOCUMENTAL_PENDING_HUMAN_GATES' FROM inserted CROSS JOIN (VALUES (2)) AS d(pantalla_id);
-- INSERT CANDIDATO B2B-RULE-RECOVERY-MFA-SEPARATION-001 LINKS B2B-AUTH-004
WITH inserted AS (INSERT INTO lf_ops.reglas(codigo,categoria,titulo,descripcion,valor_config,estado,origen,pendiente_decision,created_by) VALUES ('B2B-RULE-RECOVERY-MFA-SEPARATION-001','AUTH','MFA B2B no hereda aprobación ni clave temporal de recuperación','B2B-AUTH-004 solo concluye MFA cuando LF_AUTH_BOUNDARY verifica OTP por correo Brevo conforme a política vigente. Ni la clave temporal de recuperación, ni la aprobación de soporte, ni el aviso entregado, ni las 48 horas satisfacen MFA, crean sesión o eligen factor. La entrega Brevo requiere implementación y QA; no hay bypass SMS automático ni passkeys. Esta regla es CANDIDATO documental y no modifica AUTH-018/019/020/021/026/047 ni políticas 19/20/23/25.','{"mfa":"SERVER_VERIFIED_EMAIL_BREVO_IF_REQUIRED","recovery_proof_satisfies_mfa":false,"temporary_password_satisfies_mfa":false,"sms":"SUPPORT_CONTINGENCY_ONLY","operational":false,"identity_verified":false}'::jsonb,'CANDIDATO','LF_GOVERNANCE_PROPOSAL',true,'ARCHITECT_DRAFT') RETURNING id) INSERT INTO lf_ops.reglas_pantallas(regla_id,pantalla_id,nota) SELECT inserted.id,d.pantalla_id,'DOCUMENTAL_PENDING_HUMAN_GATES' FROM inserted CROSS JOIN (VALUES (54)) AS d(pantalla_id);
-- INSERT CANDIDATO B2B-RULE-RECOVERY-ALTERNATE-CONTACT-001 LINKS B2B-AUTH-002,B2B-AUTH-006
WITH inserted AS (INSERT INTO lf_ops.reglas(codigo,categoria,titulo,descripcion,valor_config,estado,origen,pendiente_decision,created_by) VALUES ('B2B-RULE-RECOVERY-ALTERNATE-CONTACT-001','RECOVERY','Notificación B2B entregada antes del reloj; contingencia de contacto','El reloj de 48 horas NO empieza con la solicitud. Solo el servidor lo inicia cuando (i) terminaron todas las aprobaciones requeridas según la política aplicable y (ii) cada aviso obligatorio al contacto anterior tiene evidencia de estado ENTREGADO, no solo ACCEPTED/QUEUED/SENT; inicio efectivo = instante del último de esos eventos. Rebote, entrega no confirmada o revocación posterior: estado BLOCKED o PAUSED, sin emisión de clave temporal, reasignación ni sesión; una reanudación exige nueva evidencia de entrega y readback auditado. Ante aviso fallido, soporte puede abrir una ruta alternativa gobernada y auditada, sin desbloqueo automático. Contactos candidatos exclusivamente: otro correo o celular previamente registrado y verificado de la misma cuenta antes de iniciar la recuperación, con prueba histórica de titularidad, operación de notificación idempotente y confirmación ENTREGADO; se admite reintento al contacto anterior original. No aceptar nuevos datos declarados durante la solicitud, contactos de un aprobador, terceros ni destinatarios no acreditados. Un contacto secundario NO sustituye por sí solo la notificación obligatoria anterior: la equivalencia y autoridad de sustitución siguen PENDING_HUMAN_DECISION y bloquean el reloj/la liberación hasta aprobación explícita. Solo contar 48 horas de tiempo elegible; no emitir clave temporal si aviso falló o está en PAUSED. approvers_required se resuelve desde política 20 y no se asume implementado hasta readback real.','{"wait_hours":48,"hold_start":"LAST_APPROVAL_AND_DELIVERED","approval_source":"SECURITY_POLICY_20_APPROVERS_REQUIRED_PENDING_BINDING","delivery_receipt":"DELIVERED_ONLY","failure":"BLOCK_OR_PAUSE","secondary_contact_qualifies":"PENDING_HUMAN_DECISION","status":"PROPOSAL","identity_verified":false}'::jsonb,'CANDIDATO','LF_GOVERNANCE_PROPOSAL',true,'ARCHITECT_DRAFT') RETURNING id) INSERT INTO lf_ops.reglas_pantallas(regla_id,pantalla_id,nota) SELECT inserted.id,d.pantalla_id,'DOCUMENTAL_PENDING_HUMAN_GATES' FROM inserted CROSS JOIN (VALUES (52),(56)) AS d(pantalla_id);
-- INSERT CANDIDATO REG_CLIENT_RECOVERY_ALTERNATE_CONTACT_001 LINKS REC_001
WITH inserted AS (INSERT INTO lf_ops.reglas(codigo,categoria,titulo,descripcion,valor_config,estado,origen,pendiente_decision,created_by) VALUES ('REG_CLIENT_RECOVERY_ALTERNATE_CONTACT_001','RECOVERY','Notificaciones previas Cliente Q11 y ruta alternativa bloqueada','El reloj de 48 horas NO empieza con la solicitud. Solo el servidor lo inicia cuando (i) terminaron todas las aprobaciones requeridas según la política aplicable y (ii) cada aviso obligatorio al contacto anterior tiene evidencia de estado ENTREGADO, no solo ACCEPTED/QUEUED/SENT; inicio efectivo = instante del último de esos eventos. Rebote, entrega no confirmada o revocación posterior: estado BLOCKED o PAUSED, sin emisión de clave temporal, reasignación ni sesión; una reanudación exige nueva evidencia de entrega y readback auditado. En Q11 se exige que el celular y correo anteriores reciban aviso ENTREGADO; si falla cualquiera, no liberar, pausar y conservar audit trail. Ante aviso fallido, soporte puede abrir una ruta alternativa gobernada y auditada, sin desbloqueo automático. Contactos candidatos exclusivamente: otro correo o celular previamente registrado y verificado de la misma cuenta antes de iniciar la recuperación, con prueba histórica de titularidad, operación de notificación idempotente y confirmación ENTREGADO; se admite reintento al contacto anterior original. No aceptar nuevos datos declarados durante la solicitud, contactos de un aprobador, terceros ni destinatarios no acreditados. Un contacto secundario NO sustituye por sí solo la notificación obligatoria anterior: la equivalencia y autoridad de sustitución siguen PENDING_HUMAN_DECISION y bloquean el reloj/la liberación hasta aprobación explícita. Selfie: NO_AUTORIZADA_POR_AHORA, no implementada, sin reglas operativas, sin captura ni envío; proveedor IDV PENDING_SELECTION y sin atribución de VERIFIED automático.','{"hold_hours":48,"approvers":"TWO_DISTINCT_PEOPLE","old_notification_channels":["OLD_PHONE","OLD_EMAIL"],"delivery":"ALL_DELIVERED","failure":"BLOCK_OR_PAUSE","secondary_contact_qualifies":"PENDING_HUMAN_DECISION","selfie":"NOT_ACTIVE","idv_provider":"PENDING_SELECTION","identity_verified":false}'::jsonb,'CANDIDATO','LF_GOVERNANCE_PROPOSAL',true,'ARCHITECT_DRAFT') RETURNING id) INSERT INTO lf_ops.reglas_pantallas(regla_id,pantalla_id,nota) SELECT inserted.id,d.pantalla_id,'DOCUMENTAL_PENDING_HUMAN_GATES' FROM inserted CROSS JOIN (VALUES (58)) AS d(pantalla_id);
